#include <pthread.h>
#include <stdio.h>

void *thread_function(void *arg) {
    printf("Thread is working\n");
    return NULL;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, thread_function, NULL);
    printf("Main is working\n");
    pthread_join(thread, NULL);
    return 0;
}
